INSERT INTO `blog` (`blog_id`, `blog_name`, `blog_datee`, `blog_desc`, `blog_path`, `blog_status`, `blog_date`) VALUES
(5, 'How does the Student Management System', '2023-09-29', '<p>Have you ever tried pulling up the marks of a student who has recently passed an exam? You have probably done it, but it&rsquo;s quite tedious and time-consuming.</p>\r\n', 'assets/uploads/blog14.jpg', 1, '2023-10-04 01:04:13'),
(6, 'Smart Classrooms are the way ahead', '2023-09-29', '<p>Over the past few years, technology has transformed our lives in many ways, and classrooms are no exception.</p>\r\n', 'https://www.harvestgreenmontessori.com/assets/uploads/blog23.jpg', 1, '2023-09-29 19:56:47'),
(7, 'Learning Management System helps organise academic schedules', '2023-09-12', '<p>If there is software that has witnessed tremendous adoption in the past few years, it is&nbsp;<a href=\"https://leadschool.in/school-owner/solutions/learning-management-system/\" rel=\"noopener\" target=\"_blank\"><strong>Learning Management System</strong></a>&nbsp;(LMS). Especially during the COVID-19 pandemic, many educational institutes shifted from traditional classrooms to virtual classrooms to mitigate the impact of learning loss. The technology that made the shift much easier was none other than the&nbsp;<strong>learning management system</strong>. According to Educause,&nbsp;<em>over 77% of higher education faculty strongly agree that an LMS is critical to their teaching</em>.</p>\r\n', 'https://www.harvestgreenmontessori.com/assets/uploads/blog31.jpg', 1, '2023-09-29 19:58:44');
