(50, 'Kiarah Portraits', 'Portraits', 'kiarahphotos@gmail.com', '6666555222', '1', 'Hi there, \r\n\r\nI hope you are doing great. I am writing to request if you would be interested in a complimentary Picture Day fundraiser, where we will donate twelve percent of the sales back to your school.\r\n\r\nThe Director will receive complimentary digital group pictures and headshots. Plus every kid will get a free seasonal gift box of two pencils, one eraser, a sharpener and a ruler. There is no minimum and no pre-ordering is required. Parents can view digital proofs before ordering from vario', 1, '2024-02-08 13:08:28'),
(51, 'Mike Adamson\r\n', 'Mike Adamson\r\n', 'mikePeneoupleEmpopay@gmail.com', '89287384124', '2', 'If you are looking to rank your local business on Google Maps in a specific area, this service is for you. \r\n \r\nGoogle Map Stacking is a highly effective technique for ranking your GMB within a specific mile radius. \r\n \r\nMore info: \r\nhttps://www.speed-seo.net/product/google-maps-pointers/ \r\n \r\n \r\nThanks and Regards \r\nMike Mike Adamson\r\n \r\n \r\nPS: Want a comprehensive local plan that covers everything? \r\nhttps://www.speed-seo.net/product/local-seo-bundle/', 1, '2024-02-09 07:09:53'),
(52, 'Neil Lui', 'Neil Lui', 'neil.lui@outlook.com', '02.10.57.97.15', '5', 'I recommend exploring this tool as a potential avenue for leveraging marketing strategies to generate revenue.\r\n\r\nhttps://bit.ly/RapidProfitMachine1113\r\n\r\nhttps://www.wildaitools.com/\r\n\r\n', 1, '2024-02-10 18:44:05'),
(53, 'Rachel', 'Miller', 'taxcredit@1099.expert', '3108184024', '1', 'Did you get your PPP Loans, SBA Loan or any other type of Covid assistance or help? \r\n\r\nIf you got an ERC loan then this is NOT for you. \r\n\r\nOnly if you are self employed can you qualify. This will last until Apirl 30, 2024. This is the LAST of the COVID money. You have a very limited time to see how much please use this tax credit calculator https://1099.expert/calculator/ \r\n\r\nif you want to verify this please go to the IRS website at: https://www.irs.gov/pub/taxpros/fs-2022-15.pdf', 1, '2024-02-11 02:47:18'),
