INSERT INTO `popup` (`popup_id`, `popup_name`, `popup_desc`, `popup_path`, `popup_status`, `popup_date`) VALUES
(1, 'Now Enrolling!', 'August 2025-2026 school year!<br>Ages: Infants (3months) to First Grade<br>Before/After school from James C. Neill Elementary only', 'https://www.harvestgreenmontessori.com/assets/uploads/2024_Spring_Enrollment.jpg', 1, '2025-02-20 10:51:39');
INSERT INTO `program` (`program_id`, `program_name`, `program_title`, `program_title_two`, `program_title_three`, `program_title_four`, `program_title_five`, `program_title_six`, `program_title_seven`, `program_title_eight`, `program_title_nine`, `program_title_ten`, `program_title_eleven`, `program_desc`, `program_desc_two`, `program_desc_three`, `program_desc_four`, `program_desc_five`, `program_desc_six`, `program_desc_seven`, `program_desc_eight`, `program_desc_nine`, `program_desc_ten`, `program_desc_eleven`, `program_display`, `program_display_two`, `program_display_three`, `program_display_four`, `program_display_five`, `program_display_six`, `program_display_seven`, `program_display_eight`, `program_display_nine`, `program_path`, `program_path_two`, `program_status`, `program_date`) VALUES
(16, 'Infant', 'Cognitive Developement', 'Fine Motor Skill Developement', 'Gross Motor Skills', 'Speech and Language Skill Developement', 'All that we ourselves are has been made by the<br> child we were in the first two years of our lives.', 'Some Highlights Of Our Infant Care Program Are:', 'Social and Emotional Developement', ' ', ' ', ' ', ' ', '<span class=\"text-highlight\">At HGM, </span>we make everyday a wonderful adventure & encourage the infants to explore the world around them. We provide a safe trusting environment that allows every child to develop a bond & trusting relationship with the teacher. Our Infant rooms are open as soon as your baby starts to find their feet. We help them learn how to walk properly & become more coordinated. A wide variety of resources that includes audio, visual and physical are used to stimulate the child. Our structured programs ensure balance between learning and relaxation and includes specific play and sleep time. Curriculum also includes art, music, and tactile activities to develop their senses, confidence and concentration. We ensure the child spend much of their day experimenting, exploring and beginning to socialize. Child\'s safety and security is our highest priority and each child will be assigned a \"primary care giver\" who monitors daily schedule, maintains written communication with parents and follows individual care instructions. Extra care is taken when Infants are held while being bottle-fed, and with necessary sanitization requirements. Specific measures are in place to ensure hand washing and diapering are performed to maintain the highest level of cleanliness and hygiene. All materials child uses will be age appropriate and sanitized.', '<span class=\"fa fa-star text-danger my-2\"></span> Our infant class is spacious and specially designed for their safety and comfort.<br>\r\n<span class=\"fa fa-star text-success my-2\"></span> Each child has their designated crib and bedding labeled with their name.<br>\r\n<span class=\"fa fa-star text-primary my-2\"></span> Babies can move around and explore as they begin to crawl.<br>\r\n<span class=\"fa fa-star text-warning my-2\"></span> We encourage group activities like singing, playing, reading picture books, etc. to build strong social bonds in early years.<br>\r\n<span class=\"fa fa-star text-danger my-2\"></span> Activities (quiet and active) are balanced and maintained between both indoor and outdoor.<br>\r\n<span class=\"fa fa-star text-success my-2\"></span> Teacher and Child ratio is strictly maintained as per Texas minimum standards', 'Starting from birth, infants learn to interact with other people to understand and control their own emotions. They develop relationships with people right around them hence we focus on developing social skills, which is an important aspect in the children’s development, and this includes self-control and making friends which in turn helps children succeed in both school and life. Our teachers help every child in learning how to develop friendship, communicate emotions, and to deal with challenges. Our teachers ensure that the child develops trust, empathy, compassion, and a sense of right and wrong.', 'Cognitive development is the ability to learn and resolve problems. Cognitive skills encompass your baby\'s ability to think, learn, understand and explore the environment. From birth, your baby soaks in information and starts building his/her cognitive skills.', 'Fine motor skills development is a very important skill for every young child. These skills help the child to start using small muscles, specifically their hands and fingers, to pick up small objects, hold a spoon, turn book pages, that way they explore their own bodies and world around them. Their fine motor skills develop as their whole body starts to move and become more stable. Our teachers ensure that they offer children an exciting and safe play opportunity to help them develop their fine a period.', 'Gross Motor development skills involves the larger, stronger muscle groups. In early ages it is the development of these types of muscles which allows the baby to hold their head up, crawl, sit, and later walk, run, and skip. These gross skills also help the child’s awareness, reaction speed, balance and strength.', 'The infants’ language development is influenced mostly by what they hear around them and what is spoken to them. The more babies are exposed to the language the better their communication skills will be. Our teachers make sure that the child is given the best practices to achieve his/her language development goal.', '', '', '', '', ' ', ' ', ' ', ' ', ' ', 'd-none', ' d-none', ' d-none', ' d-none', 'https://www.harvestgreenmontessori.com/assets/uploads/Infant.png', 'https://www.harvestgreenmontessori.com/assets/uploads/Infant2.png', 1, '2024-01-04 15:55:53'),
(17, 'Toddler', 'Practical Life', 'Sensorial', 'Language', 'Mathematics', 'Only through freedom and environmental<br> experience is it practically possible for human<br> development to occur.', 'Some Highlights Of Our Infant Care Program Are:', 'Geography', 'Science', 'Motor Skills', 'Library', 'Art', '<span class=\"text-highlight\">Our</span> Toddler program is designed to take advantage of toddler\'s natural drive to act independently. Harvest Green Montessori advances each child\'s growth and development through a rich and well-prepared environment designed exclusively for toddlers. We strongly believe that key components of a successful toddler program include a prepared environment, meaningful activity, collaboration between parents and teachers. Toddler classrooms are carefully designed to meet the physical needs of the children. Once the child become very steady on their feet, we introduce them to Toddlers room where they are introduced to more advanced equipment, more structured daily schedule of activities and arts/crafts. Toddlers are trained on essential needs including potty-training, introduction to group learning, basic communication, vocabulary and simple sentences. We train them to retain vast amounts of information and to make ideas. We ensure they have enough sleep time as part of their daily routine. Extra measures are in place to ensure hand washing and diapering are performed to maintain the highest level of cleanliness and hygiene. Toddlers are gently guided and encouraged to be safe indoors and outdoors, which is specially designed to match the needs of active toddlers. All materials child uses will be age appropriate and sanitized.', '<span class=\"fa fa-star text-danger my-2\"></span> An environment that emphasizes responsibility, self-discipline and mutual respect.<br>\r\n<span class=\"fa fa-star text-success my-2\"></span> Daily morning and afternoon activities for outdoor play as weather permits.<br>\r\n<span class=\"fa fa-star text-primary my-2\"></span> A curriculum that emphasizes independence.<br>\r\n<span class=\"fa fa-star text-warning my-2\"></span> An orderly classroom with well-prepared work areas.<br>\r\n<span class=\"fa fa-star text-danger my-2\"></span> Opportunities to develop self-help skills such as potty training, hand washing, and feeding.<br>\r\n<span class=\"fa fa-star text-success my-2\"></span> Options for extra enrichment activities.<br>\r\n<span class=\"fa fa-star text-primary my-2\"></span> A teacher who guides rather than directs.', 'Our lessons in geography introduce the concept of a globe and create a framework for a whole world to self-world learning. ', 'Practical life activities encourage the child to take care of the environment with size-appropriate materials. The children are taught several indoor and outdoor skills which include gardening, dusting, mopping, sweeping, and washing. The toddler is also directed to take care of himself by washing hands, hanging clothing, managing personal items and toiletries.', 'The toddler can discover and explore the world around him/her through their five senses. For Example- Sound cylinders are one of the easiest and most delightful Montessori sensorial materials children love to hear. The different sounds each cylinder makes helps to awaken and refine the child\'s auditory sense.', 'Language develops at a rapid rate during the toddler years. Sandpaper letters help the child learn the phonetics of the alphabet. Naming cards and matching help to introduce foundations for alphabet and language. Stories, finger plays, singing and conversation time encourage both social and language skills.', 'The toddler uses hands-on materials for learning concrete math concepts. Toddlers begins to understand Number concepts, which includes Quantity, Symbols, meaning of zero etc. Child is also exposed to understand language used in performing simple single-digit addition.', 'We introduce toddlers to a wonderful collection of safe, fun, and easy science activities. Toddlers will learn about the environment, nature activities, living and non-living things, land and water, and sink and float to enable the young minds with the skills they need.', 'The toddler is refining both fine motor skills and gross motor skills. Fine motor skills are given a boost through practical life activities such as pouring, sorting, etc. Gross motor skills are given a boost during physical activities like rhythm/music movement and outdoor play.', 'Our Library programs support and supplement the curriculum and educational programs for all age groups. Toddler students are taught how to handle books and they enjoy listening to a variety of stories and story-telling activities by the teacher.', 'Art is one of the many ways children learn how to express themselves and is a way for children to communicate their feelings with others. It is through art that children develop their fine motor skills. At HGM, we provide art activities that help children explore and learn how to use their creativity.', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', 'https://www.harvestgreenmontessori.com/assets/uploads/Toddler1.png', 'https://www.harvestgreenmontessori.com/assets/uploads/Toddler_1.png', 1, '2024-01-04 15:44:06'),
(18, 'Transition', 'Grace and Courtesy', 'Practical Life', 'Sensorial materials', 'Language', 'Only through freedom and environmental<br> experience is it practically possible for human<br> development to occur.', 'KEY AREA OF FOCUS', 'Mathematics', 'Geography', 'Science and Nature', 'Art', ' ', '<span class=\"text-highlight\">At HGM,</span> our transition program is to assist the child as they fulfill the basic human tasks of trust, separation, independence and self-control. The focus is both on curriculum and materials to help the toddler respond to rapid and conflicting changes of this development age. Harvest Green Montessori advances each child\'s growth and development through a rich and well-prepared environment designed just for transition. We strongly believe that key components of a successful transition program include a prepared environment, meaningful activity, collaboration between parents and teachers. All materials are age-appropriate and sanitized. Extra measures are in place to ensure potty train and hand washing are performed to maintain the highest level of cleanliness and hygiene. Transition are gently guided and encouraged to explore safely indoors and outside on our playground, which is specially designed to match the needs of active transition.', '<span class=\"fa fa-star text-danger my-2\"></span> Children experiment with different letter sounds and start to explore characters and story plots.<br>\r\n<span class=\"fa fa-star text-success my-2\"></span>Group activities help children learn to follow directions, take turns and develop friendships.<br>\r\n<span class=\"fa fa-star text-primary my-2\"></span> Children explore number concepts and practice comparing, classifying and measuring. They begin using number lines.<br>\r\n<span class=\"fa fa-star text-warning my-2\"></span>  Children practice fine motor skills with puzzles and improve balance through fun activities.<br>\r\n<span class=\"fa fa-star text-danger my-2\"></span> Children clap, move and sing songs; create art by folding, cutting and coloring; and act out lyrics to favorite songs.<br>\r\n<span class=\"fa fa-star text-success my-2\"></span> Children explore the traditions of other cultures and learn Spanish vocabulary for farm animals, family members and numbers 1-10.<br>\r\n<span class=\"fa fa-star text-primary my-2\"></span> Children perform simple experiments, learn about the weather, and compare personal characteristics.<br>\r\n<span class=\"fa fa-star text-warning my-2\"></span> Children are introduced to basic technology vocabulary and begin to use the mouse and keyboard.', 'Early mathematics activities are designed to transform ideas into actions using concrete learning materials resulting in making abstract concepts clear to the learner. These experiences explore the underlying fundamentals of algebra, geometry, logic, and statistics. Operational principles such as addition, multiplication, division, and subtraction.', 'Grace and Courtesy in reaction to the young child\'s need for order. The Primary Transition Class is the perfect place to begin these exercises in Grace and Courtesy because the child at the end of the first plane of development is not yet self-conscious and doesn\'t realize what the child is doing at times. Grace and Courtesy lessons are given to each child in the environment and usually in a group. This allows the child to have a clear understanding as well as a place to perfect themselves with each other. Grace and Courtesy provides manners and hones the child\'s skills. In the end, the child will have incorporated these graces and courtesies into his everyday life, which will allow for a more pleasant classroom and environment wherever the child may go.', 'Practical Life is the true heart of a Montessori classroom. By working on real-life tasks, children develop their independence, coordination, and concentration through a variety of activities that explore daily activities such as eating, cutting, polishing, sweeping, dressing, and cleaning. Teachers demonstrate these tasks that explore caring for the environment and the self, encouraging responsibility, and promoting self-esteem.', 'Sensorial materials in the Montessori classroom are made to help the child explore the world through their senses. Each of the sensorial materials isolates one quality such as color, weight, shape, texture, size, sound, and smell. These materials help children figure out the difference between information to categorize and relate new information to what they already know. Sensorial Materials are largely self- correcting, so the child can accomplish most of these exercises alone. Children find a sense of order in these materials and acquire joy in learning that their environment has order.', 'Language development is vital to human development. Our Montessori environment is rich in oral language opportunities, allowing the child to experience conversations, stories, and poetry. The sandpaper letters help children link sound and symbol effortlessly, encouraging the development of written expression and reading skills. To further reading development, children are exposed to the study of grammar. Language experiences encourage children to master, and blend sounds to build words, instead of the traditional memorization of \"sight words.\" This gives children the tools to read at a higher level.', 'Geography begins with the study of maps and the two hemispheres of Earth and becomes more and more detailed as children will learn about countries and Continents. The very young child will use the wooden puzzle maps as puzzles, but the older child can use the pieces as a guide as he makes his own maps, labeled with his own handwriting when he is ready.', 'Children are introduced to many topics and learn to make predictions in their Science and Nature activities. The land and water work, introducing the concepts of Lake and Island, is closely connected to the geography curriculum. Children learn about volcanoes, the layers of the Earth and the solar system. Children will go on nature walks and then research the leaves and seed they have found. Activities include Sink or Float, Living or Non-Living, Magnetic or Non-Magnetic, Land and Water Forms, the Structure of the Earth and Botany.', 'Art is one of the many ways children express themselves. Art is a way for children to communicate their feelings. It is through art that children develop their fine motor skills. In the Montessori environment, we provide open-ended art activities that help children explore and use their creativity.', '', '', '', '', '', '', '', '', '', 'd-none', 'https://www.harvestgreenmontessori.com/assets/uploads/Transition_1.png', 'https://www.harvestgreenmontessori.com/assets/uploads/Transition_2.png', 1, '2024-01-04 15:48:03'),
(19, 'Primary', 'Grace and Courtesy', 'Practical Life', 'Sensorial', 'Language', 'Education is a natural process carried out by the<br> human individual, and is acquired not by listening<br> to words, but by experiences in the environment.', 'Some Highlights Of Our Primary Care Program Are:', 'Mathematics', 'Geography', 'Science and Nature', 'Art', ' ', '<span class=\"text-highlight\">At HGM,</span> we recognize this as the beginning of control and coordination of mind and body. In the process, children acquire language (s), develop motor, gross, and cognitive skills, copy the social skills of the adults around them and acquire expectations about how the world will treat them when they move on. The Primary classroom offers the young child a highly structured curriculum specially designed for their own needs. A Montessori school has multi-age classrooms. Older students should be able to model appropriate behavior and guide their younger peers, all while making academic advancements of their own. Studies have shown that the Montessori Method provides a solid academic basis as well as exceptional social skills that prepare children well for a good academic year. Students are taught in other areas which include Grace and Courtesy, Practical life, Sensorial, Language, Math, Social studies, and Geography, Art and Music.', '<span class=\"fa fa-star text-danger my-2\"></span> The Montessori curriculum allows us to continually challenge each child at his/her own pace.<br>\r\n<span class=\"fa fa-star text-success my-2\"></span> We highly value our close working relationships with our families. This partnership is fostered through ongoing, personal communication as well as multiple conferences each year.<br>\r\n<span class=\"fa fa-star text-primary my-2\"></span> The multi-age classroom stimulates enthusiasm for learning and inspires independent thinking.<br>\r\n<span class=\"fa fa-star text-warning my-2\"></span> All of our teachers have Montessori certified with extensive experience in the classroom.<br>\r\n<span class=\"fa fa-star text-danger my-2\"></span> We provide a large outdoor, as well as an indoor space, specifically designed to meet the young child\'s need for gross motor development.<br>\r\n<span class=\"fa fa-star text-success my-2\"></span> Our program includes Montessori curriculum along with regularly scheduled enrichment activities which may include Spanish, Art and yoga. Each taught by teachers that are specifically trained in these disciplines.', 'Early mathematics activities are designed to transform ideas into actions using concrete learning materials resulting in making abstract concepts clear to the learner. These experiences explore the underlying fundamentals of algebra, geometry, logic, and statistics. Operational principles such as addition, multiplication, division, and subtraction.', 'Grace and Courtesy in reaction to the young child\'s need for order. The Primary Transition Class is the perfect place to begin these exercises in Grace and Courtesy because the child at the end of the first plane of development is not yet self-conscious and doesn\'t realize what the child is doing at times. Grace and Courtesy lessons are given to each child in the environment and usually in a group. This allows the child to have a clear understanding as well as a place to perfect themselves with each other. Grace and Courtesy provides manners and hones the child\'s skills. In the end, the child will have incorporated these graces and courtesies into his everyday life, which will allow for a more pleasant classroom and environment wherever the child may go.', 'Practical Life is the true heart of a Montessori classroom. By working on real-life tasks, children develop their independence, coordination, and concentration through a variety of activities that explore daily activities such as eating, cutting, polishing, sweeping, dressing, and cleaning. Teachers demonstrate these tasks that explore caring for the environment and the self, encouraging responsibility, and promoting self-esteem.', 'Sensorial materials in the Montessori classroom are made to help the child explore the world through their senses. Each of the sensorial materials isolates one quality such as color, weight, shape, texture, size, sound, and smell. These materials help children figure out the difference between information to categorize and relate new information to what they already know. Sensorial Materials are largely self- correcting, so the child can accomplish most of these exercises alone. Children find a sense of order in these materials and acquire joy in learning that their environment has order.', 'Language development is vital to human development. Our Montessori environment is rich in oral language opportunities, allowing the child to experience conversations, stories, and poetry. The sandpaper letters help children link sound and symbol effortlessly, encouraging the development of written expression and reading skills. To further reading development, children are exposed to the study of grammar. Language experiences encourage children to master, and blend sounds to build words, instead of the traditional memorization of \"sight words.\" This gives children the tools to read at a higher level.', 'Geography begins with the study of maps and the two hemispheres of Earth and becomes more and more detailed as children will learn about countries and Continents. The very young child will use the wooden puzzle maps as puzzles, but the older child can use the pieces as a guide as he makes his own maps, labeled with his own handwriting when he is ready.', 'Children are introduced to many topics and learn to make predictions in their Science and Nature activities. The land and water work, introducing the concepts of Lake and Island, is closely connected to the geography curriculum. Children learn about volcanoes, the layers of the Earth and the solar system. Children will go on nature walks and then research the leaves and seed they have found. Activities include Sink or Float, Living or Non-Living, Magnetic or Non-Magnetic, Land and Water Forms, the Structure of the Earth and Botany.', 'Art is one of the many ways children express themselves. Art is a way for children to communicate their feelings. It is through art that children develop their fine motor skills. In the Montessori environment, we provide open-ended art activities that help children explore and use their creativity.', '', '', '', '', '', '', '', '', '', 'd-none', 'https://www.harvestgreenmontessori.com/assets/uploads/Primary.png', 'https://www.harvestgreenmontessori.com/assets/uploads/Primary1.png', 1, '2024-01-04 15:51:19'),
(20, 'Kindergarten_First_Grade', 'Advanced Practical Life', 'Sensorial', 'Language', 'Mathematics', 'When the child begins to think and to make use of<br> the written language to express his rudimentary<br> thinking, he is ready for elementary work; and this<br> fitness is a question not of age or other incidental<br> circumstance but of mental maturity.', 'Some Highlights Of Our Kindergarten Program Are:', 'Physical and Cultural Geography', 'Science and Nature', 'Fine Art', 'Spanish and Other Languages', ' ', '<span class=\"text-highlight\">At HGM,</span> we encourage the children to work at their own pace in a non-competitive environment to learn abstract principles. In the process, the child will gain deeper understanding of themselves and develop a sensitivity to others using language to express empathy. Kindergarteners act as positive peer models for their younger classmates, assuming positions of responsibility that further strengthen their own capabilities and self-esteem. Everything that children have learned in previous years comes together in Kindergarten, giving children a readiness to meet new challenges. Students are taught in a wider area that includes practical life, Sensorial, Language, Math, Social studies, Geography, Art and Music. Our children are equipped with a strong all-rounded foundation, to be able to out-perform their peers at the elementary school of their choice. Our teachers act as guides for students, facilitating their learning in the classroom based on their developmental levels. Individual attention is provided in developing their lesson plans. The Kindergarten curriculum at HGM is carefully structured according to the Kindergarten Common Core Standards and is integrated to demonstrate the connections between the different areas of a Montessori classroom.', '<span class=\"fa fa-star text-danger my-2\"></span> The Montessori curriculum allows us to continually challenge each child at his/her own pace.<br>\r\n<span class=\"fa fa-star text-success my-2\"></span> We highly value our close working relationships with our families. This partnership is fostered through ongoing, personal communication as well as multiple conferences each year.<br>\r\n<span class=\"fa fa-star text-primary my-2\"></span> The multi-age classroom stimulates enthusiasm for learning and inspires independent thinking.<br>\r\n<span class=\"fa fa-star text-warning my-2\"></span> All of our teachers have Montessori certified with extensive experience in the classroom.<br>\r\n<span class=\"fa fa-star text-success my-2\"></span> We provide a large outdoor, as well as an indoor space, specifically designed to meet the young child\'s need for gross motor development.<br>\r\n<span class=\"fa fa-star text-primary my-2\"></span> Our program includes Montessori curriculum along with regularly scheduled enrichment activities which may include Spanish, Art and yoga. Each taught by teachers that are specifically trained in these disciplines.', 'In our Geography curriculum, our students look at the Earth, our home, study its weather, seasons, its various formations of land and water, and learn its place in the Solar System. A major portion of this curriculum consists of the study of world maps. Children explore the continents of the world, their culture and wildlife, and learn about the states that form United States of America. History and geography begin with the study of maps and the two hemispheres of Earth and becomes more and more detailed as children will learn about countries and Continents. The very young child will use the wooden puzzle maps as puzzles, but the older child can use the pieces as a guide as he makes his own maps, labeled with his own handwriting when he is ready.', 'When children enter the Montessori Kindergarten program, they are already familiar with basic practical life activities. Now, they are presented with the opportunity to apply their acquired skill set to real world activities. They also learn basic etiquette and sewing where they create projects using running stitch, cross stitch, and blanket stitch. These Advanced Practical Life activities help children develop a high level of concentration, patience, and improve their fine motor skills, while evoking a sense of respect for others and their environment.', 'Sensorial materials in the Montessori classroom are designed to help the child explore the world through their senses. Each of the sensorial materials isolates one defining quality such as color, weight, shape, texture, size, sound, and smell. The materials help children to distinguish, to categorize, and to relate new information to what they already know. The Sensorial Materials are largely self- correcting, so the child can accomplish the exercise alone. Children find a sense of order in these materials and acquire joy in learning that their environment has order.', 'The development and sophistication of the child\'s oral and written language are critical to his/her success in school. An insatiable intellectual curiosity demands that knowledge not only is absorbed and retained but expressed and acknowledged by others in the learning environment. Careful attention is paid to the child\'s: Reading comprehension, Composition (descriptive, expository, persuasive), Language arts, Grammar, Sentence construction, Vocabulary, Study and use of different verbs and their tenses, Oral expression. These skills are taught in isolation and in direct association with writing and reading, which is where the child\'s true interests lie. Didactic materials, which are as precise, orderly, and appealing as those in mathematics and geometry, are the means for delivering instruction and enabling mastery.', 'All worldly functions are related to mathematics in one way or another. Thus, the ability to apply math skills in other areas of study such as art and sensory activities is most beneficial. The four basic mathematical operations of addition, subtraction, multiplication, and division are taught in detail, building on the skills learned in Pre-Kindergarten. Students work with the number categories of units, tens, hundreds, and thousands, comprehend the concept of zero and learn to tell time. They also learn to count into 2\'s, 5\'s and 10\'s. A majority of the math curriculum in dedicated to Geometry and related lessons include the Geometry Cabinet, Geometric Solids, Constructive Triangles and the Binomial and Trinomial Cubes.', 'Children are introduced to many topics and learn to make predictions in their Science and Nature activities. The land and water work, introducing the concepts of Lake and Island, is closely connected to the geography curriculum. Children learn about volcanoes, the layers of the Earth and the solar system. Children will go on nature walks and then research the leaves and seed they have found. Activities include Sink or Float, Living or Non-Living, Magnetic or Non-Magnetic, Land and Water Forms, the Structure of the Earth and Botany.', 'Our students are exposed to several famous artists and their works. Children are introduced to the art techniques used by these established artists and are provided with an opportunity to experiment with various art media to create their own unique works of art.', 'Children are taught to speak words, sentences, and rhythms of Spanish and other languages through games, songs, and activities. Lessons initially include counting, colors, and basic vocabulary.', '', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', 'd-none', 'https://www.harvestgreenmontessori.com/assets/uploads/Kindergarten2.png', 'https://www.harvestgreenmontessori.com/assets/uploads/Kindergarten11.png', 1, '2024-01-07 11:37:05'),
(21, 'Enrichment', 'Yoga', 'Homework Help', 'Language Classes', 'Gardening', 'Character formation cannot be taught. It comes<br> from experience and not from explanation.', 'Did you know that in addition to our well-rounded Montessori program, that we also offer the following Enrichment activities?', 'General Music', ' ', ' ', ' ', ' ', '<h4 class=\"fw-5 f-36\">Montessori Enrichment</h4>\r\n In addition to educating your child using the Montessori Method we strive to promote all rounded development of each child by integrating; general music, yoga, gardening, language introduction and homework help for school age students. All offered at NO EXTRA CHARGE and are included in the regular tuition.', '  ', 'Music is a universal language that is made of patterns and sequences. Not only does music build new pathways in the brain that reinforce mathematical and reading concepts, music can also increase your child’s independence and confidence. Music is an oppor', 'Yoga for preschool is a perfectly balanced program that teaches children the art of yoga. Our curriculum combines yoga stretching and poses with aerobic-style exercises. This allows the students the opportunity to get their energy out as we develop their strength, stamina, balance, and agility and show them how to calm their bodies. Classes begin with a warm up followed by cardiovascular activity and stretching exercises. Children learn to stretch and cool down as each class begins early morning', 'Homework help is offered to school age students needing additional guidance in working through more difficult topics. Our school age students will also have access to our computer lab which will facilitate online math and other web-based sites assigned by the school.', 'Studies have shown that learning a second languages like Hindi and Spanish also improves overall cognitive development. In addition to learning, speaking, reading and writing in a new language, children can improve standardized test scores, critical thinking skills, problem-solving skills and greater mental flexibility. Our classes are fun and interactive, allowing kids to stay engaged and learn together through a variety of activities.', 'Gardening helps students engage in learning while enjoying nature outdoors in a relaxed setting. It can also help students learn how to take better care of the environment and the nutritional value in organic foods. Children will learn how to care and maintain their own classroom garden; wash and prepare the fruits and vegetables they will enjoy.', '', '', '', '', ' ', ' ', ' ', '  ', ' ', 'd-none', 'd-none', 'd-none', 'd-none', 'https://www.harvestgreenmontessori.com/assets/uploads/Enrichment_inside1.png', 'https://www.harvestgreenmontessori.com/assets/uploads/Enrichment_inside2.png', 1, '2023-11-08 15:50:10'),
(22, 'School Age', 'Soccer Shots', 'Basketball', ' Music and Fine Arts', 'STEAM', 'Such experiences is not just play… It is work he<br> must do in order to grow up.', 'Some Highlights Of Our After Care Program Are:', 'Martial Arts', 'Chess', ' ', ' ', ' ', '<span class=\"text-highlight\">Our</span> After-School educational program offers a safe, enriching, and exciting environment for children. Students can complete their schoolwork with the assistance of our teachers. Students can also wind down from their day, by exploring creative arts, using technology, and engaging in physical activity.', ' ', 'Martial arts are fun activities for young children. Each session includes exercises to develop balance, coordination, and gross motor skills. Our children run, jump, kick, and have a great time while improving their athleticism.', 'Soccer shots is a uniquely designed program that will introduce soccer to your child in a fun, safe and controlled environment which offers basic soccer skills, games, competitions, and prizes for your child. The program also emphasizes fun character-forming lessons such as respect, honesty, sharing, teamwork, patience, and encouragement.', 'As children grow, athletics become more competitive. This basketball provides a great opportunity for a beginning basketball player to learn the skills necessary to be successful in the game. It also provides experienced players with the ability to hone their skills on the court. A focus on basic skills such as dribbling, lay ups, passing, shooting, and defense, along with a variety of drills and mini games will prepare your athlete for basketball season .', 'Children naturally respond to multi-sensory learning opportunities, such as music and the visual arts. They use all five senses (sight, smell, sound, touch, taste) to activate specific neurons in the brain. For young children, multi-sensory activities provide more learning opportunities than single-sensory activities because more of the brain becomes involved in the lesson.', 'Steam stands for science, technology, engineering, and math. This program helps students improve in these fields and helps them get better at math and computer science.', 'Chess helps students strengthen their mind and gain confidence in other areas. It is also a strategy game making the students more strategic in other fields.', '', '', '', ' ', ' ', ' ', ' ', ' ', ' ', 'd-none', 'd-none', 'd-none', 'https://www.harvestgreenmontessori.com/assets/uploads/B4_after.png', 'https://www.harvestgreenmontessori.com/assets/uploads/after_care.png', 1, '2024-01-06 11:27:57'),
(23, 'Summer Camp', ' ', ' ', ' ', ' ', ' We found individual activity is the one factor that stimulates and produces development.', ' ', ' ', ' ', ' ', ' ', ' ', ' <span class=\"text-highlight\">Summer Camp</span><br><br>\r\nWelcome to the HGM Summer Camp Guide where you will find fun and enriching camps for children of all ages and interests.<br><br>\r\nLook forward to seeing your children become more confident, independent and responsible as they make new friends and learn important skills.<br><br>\r\nAs we know that summer camps play an important part in the development of a child, we have curated some exciting activities and camps to increase the overall skills of all the children. From science and art camps to sports week, we have set 360 degree grooming activities for the kids.<br><br>', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', 'd-none', 'd-none', 'd-none', 'd-none', 'd-none', 'd-none', 'd-none', 'd-none', 'd-none', 'https://www.harvestgreenmontessori.com/assets/uploads/summer_camp_img.png', '', 1, '2023-12-30 22:41:45');
INSERT INTO `testimonial` (`t_id`, `t_name`, `t_path`, `t_path_two`, `t_msg`, `t_gender`, `t_design`, `t_status`, `t_date`) VALUES
(15, 'Jasmin', 'https://www.harvestgreenmontessori.com/assets/uploads/253.png', 'https://www.harvestgreenmontessori.com/assets/uploads/VID-20231028-WA0002102.mp4', ' ', 'Female', ' ', 1, '2024-01-15 15:01:39'),
(16, 'Julie Dees', 'assets/uploads/2532.png', '', 'A wonderful school!! We had our toddler join and the school quickly became a second home to him. He had always been home with me, but he very quickly grew to love the school. He gets excited when he sees his uniform in the morning and jumps out of my arms and into the teachers arms when we get there. He comes home with Some many cute things he learns and they are always doing fun crafts and other great developmental activities. The teachers all really care and the entire team, including the Dire', '', ' ', 1, '2023-11-28 00:10:45'),
(17, 'Emily Pacheco', 'assets/uploads/2533.png', '', 'It is always parents\' wish or want to have a kind, caring, loving teacher for their child. Our little Samantha is under Ms. Kumar partnered by Ms. Liz.... could still remember the first two days (2) when our little girl came to Primary 2 class... she cannot stop crying for fear to be left alone to someone a stranger to her. But as days go by, Samantha became so confident, without fear but happy and excited to come to school every single day. She have learnt to socialize with kids and adults and ', '', ' ', 1, '2023-11-28 00:11:32'),
(18, 'Amit Kumar', 'assets/uploads/man1.png', '', 'Mrs. Kumar is an outstanding kindergarten teacher. She creates a warm and welcoming classroom environment that allows each student to thrive. Her lesson plans are engaging and interactive, and she has a great way of making learning fun for the kids. My daughter has grown so much academically and socially under her guidance. She is patient, kind, and truly cares about her students. We are so grateful to have her s our daughter\'s teacher and highly recommend her to any parent looking for an except', '', ' ', 1, '2023-11-28 00:12:56'),
(19, 'Aunali Siraj Adenwala', 'assets/uploads/2534.png', '', 'I should review the hard work and Commitment of the Harvest Green Montessori Team. My Daughter, Zahra Ali -Primary 1, has been attending this for over two years. You just get this good and positive energy as soon as you walk in, and to top it off, it is an Amazing staff with so much heart anda caring mindset. Seeing my daughter excited about going to Harvest Green Montessori School here is terrific. The teacher, Ms.Hetal, and Ms.Reena try to engage and develop the kids individually. My daughter ', '', ' ', 1, '2023-11-28 00:13:41'),
(20, 'Caren Pernía', 'assets/uploads/2535.png', '', 'The teamn of teachers is very professional. They have continuously demonstrated the competence and patience required to teach and guide smal kids, based on hoW we see our son\'s progress We very much appreciate the continued communication the school provides us, covering various matters ranging from monthly calendars to extraordinary activities to our son\'s progress. The facilities are always clean and safe. Our son loves his class and his teachers!', '', ' ', 1, '2023-11-28 00:14:16'),
(21, 'Shara Swiney Dugan', 'assets/uploads/2536.png', '', 'Choosing Harvest Green Montessori school for our son RJ was a great decision, his teacher Mrs. Kumar is very kind, patient and loving with him. You can tell she loves teaching and loves working with children. Every day she greets us with a huge smile, Harvest Green Montessori is lucky to have her!', '', ' ', 1, '2023-11-28 00:15:01'),
(22, 'Deborah Money', 'assets/uploads/2537.png', '', 'We came to Montessori from a really bad experience at a different daycare. From day one we could see the difference. All the teachers are so loving and peaceful. The director does a great job with open communication. We are blessed that our son has a spot at this amazing school. Very nurturing atmosphere. Highly recommend.', '', ' ', 1, '2023-11-28 00:21:28'),
(23, 'Angelle Kelley', 'assets/uploads/2538.png', '', 'Harvest Green Montessori is a great school. | didn\'t know much of an impact they has socially, emotionally, and educationally until daughter entered Kindergarten and she stated \"this work is easy, Mrs. Hetal had us doing harder worksheets\" to her new teacher. This goes to show she was more than prepared for public school and | know if | could have | would have kept her there another year. Thank you all so much for everything. Your hard work is appreciated.', '', ' ', 1, '2023-11-28 00:23:11'),
(24, 'Saralyn Mclver', 'assets/uploads/2539.png', '', 'My daughter is in her second year in Ms. Kumar\'s primary class. My daughter loves going to school and is very bonded to Ms. Kumar. She has learned so much in this nurturing environment. The school provides nutritious meals & snacks which I also really like. We have had a wonderful experience and it\'s been a great start in school for my daughter.', '', ' ', 1, '2023-11-28 00:24:55'),
(25, 'Nadia Hobart', 'assets/uploads/2531.png', '', 'My daughter started her first day of school at 3 years old on HGMS. Now, she\'s almost 5yo and everyday she goes happy to school and I pick her up with an smile on her face too. I saw the progress on her development in knowledge and social skills. They put focus on each child and always try to do their best for them. I\'m glad we had Ms. Kumar and Ms. Fatima in this process. I really recommend Harvest Green Montessori!', '', ' ', 1, '2023-11-28 00:26:19'),
(26, 'Crystal Sherrod Harris', 'https://www.harvestgreenmontessori.com/assets/uploads/253.png', '', 'We are very pleased with Harvest Green Montessori School (HGMS). My now 19-month- old son was previously at a school where we knew everyone and we were very comfortable there, but it was about 15-20 minutes from home. After our daughter started elementary school, we knew we had to get him closer to home. We looked at various schools, but felt at home with HGMS. I love so many aspects of the school - the toddler playground, library, splashpad, and especially the gym! They are great with communica', '', ' ', 1, '2023-11-28 00:27:45'),
(27, 'Megha Pathak', 'https://www.harvestgreenmontessori.com/assets/uploads/253.png', '', 'Great Montessory school & very nice teachers. I see a big difference as being stay home for long time, our son started singing nursery even at home & seeing all Montessory school work that they send home end of the week is excellent. My son is happy & so mommy too !! Having nice Montessory school in community is like a Gem !', '', ' ', 1, '2023-11-28 00:28:52'),
(28, 'Anne-Laure Sojos', 'https://www.harvestgreenmontessori.com/assets/uploads/253.png', '', 'We just moved here and my youngest had a really hard time transitioning to the Montessori routine and also separating in the morning at drop off. Ms Edina and her team were so helpful in getting him. to feel more comfortable and getting him used to the new situation. We couldn\'t be happier with the team there and highly recommend it.', '', ' ', 1, '2023-11-28 00:29:52'),
(29, 'Sahil Behl', 'https://www.harvestgreenmontessori.com/assets/uploads/man1.png', '', 'Really nice facility with very caring teachers. Our daughter is in the infant class and all the teachers are very polite and helpful. Miss Shabee is exceptional at what she does, so big thank you to her. Miss Leena and Miss Tessa are extremely caring, and our daughter has a wonderful time while at the daycare woth them. Thank you!', '', ' ', 1, '2023-11-28 00:31:00'),
(30, 'Fatma G.', 'https://www.harvestgreenmontessori.com/assets/uploads/253.png', '', 'We looked at several Montessori schools around the area but this one was most welcoming during the registration process. And I\'m glad that we have joined Harvest Green. My daughter has been going to this school for a year now and we couldn\'t be happier. After a year, my daughter still goes to school with excitement and is always happy when I pick her up. All teachers, staff, and owners are very friendly and welcoming, especially Mrs. Kumar. My daughter looks up to Mrs. Kumar and we are grateful ', '', ' ', 1, '2023-11-28 00:32:31'),
(31, 'Karimat Abdulwahab', 'https://www.harvestgreenmontessori.com/assets/uploads/253.png', '', 'Harvest Green Montessori School-Private is a great school. In 3 short months I have seen such great progress in my son. Special shout out to Ms Kumar and Ms Elizabeth for been so kind and gentle with him.', '', ' ', 1, '2023-11-28 00:33:34'),
(32, 'Mandy Bui', 'https://www.harvestgreenmontessori.com/assets/uploads/253.png', '', 'Our daughter started 6 months ago in the transition room with Ms Lina, it was an easy transition from another facility because the environment was so welcoming. It\'s clear that the director and teachers go at the child\'s pace, and work with the parents to achieve mutual goals. She is now in a primary room with Ms Kumar and Ms Liz, she is flourishing! It is obvious the love and attention given to her as an individual from her teachers, and the comradeship she has with her classmates. We are so ha', '', ' ', 1, '2023-11-28 00:34:36'),
(33, 'Shara Swiney', 'https://www.harvestgreenmontessori.com/assets/uploads/253.png', '', 'Choosing Harvest Green Montessori school for our son RJ was a great decision, his teacher Mrs. Kumar is very kind, patient and loving with him. You can tell she loves teaching and loves working with children. Every day she greets us with a huge smile, Harvest Green Montessori is lucky to have her!', '', ' ', 1, '2023-11-28 00:35:41'),
(34, 'Fred Go', 'assets/uploads/man2.png', '', 'Our son has been attending Harvest Green Montessori since he was 10 months old. Since then, he\'s been in great care by both Ms. Shabee and Ms. Tamara. At the beginning, he was shy and hesitant to go to the infant room, but he quickly fell in love with the teachers and staff. Now when we drop him off, he reaches out to the teacher\'s arm. Everyday he comes home in a good mood and with a smile. Each day the teachers send us photos of him playing, learning and doing various activities. It\'s a great ', '', ' ', 1, '2023-11-28 00:36:41'),
(35, 'Candice Harris', 'https://www.harvestgreenmontessori.com/assets/uploads/253.png', '', 'We changed to HGMS about 5 months ago from a different Montessori school and I\'m so glad we made the change. My daughter\'s teachers Ms. Hetal and Ms. Reema are wonderful! They genuinely care, are creative, and have helped my daughter advance greatly in the short time we\'ve been there. I\'m really impressed with the curriculum. It\'s a beautiful school, they serve fresh healthy catered meals everyday. We love the diversity. There\'s always fun events/celebrations going on! Thanks for all you do. - T', '', ' ', 1, '2024-01-07 11:19:01'),
(36, 'Tania Ali', 'https://www.harvestgreenmontessori.com/assets/uploads/253.png', '', 'Both my daughters have been attending Harvest Green Montessori School since we moved in January 2021. We are extremely happy with the facility and staff. The facility is clean with great activities for kids like two playgrounds, a large gym and a splash pad. They follow the Montessori curriculum which has promoted tremendous independence and growth in both my children. They also serve nutritious meals. At first my younger one cried during drop off but now she is obsessed with her teacher. We are', '', ' ', 1, '2023-11-28 00:38:53');
